// golden_test.go — T-32: the generated-golden driver.
//
// testdata/webextract_pure.golden.json is generated by
// testdiff/goldens/dump_webextract.py from the unmodified reference
// (assadigit/GitCurator @ 98f4fc7, the pinned venv's CPython 3.12.15
// stdlib for the data tables). Every section replays through this
// port and byte-compares: the constants, the 5 fixtures' full
// Extracted fields, the 86-case extract battery, the parser-level
// battery, the 95-case unescape battery (the eight spots where Go's
// stdlib diverges from Python), the utf-8 replace law, the 74-name
// charset ladder (resolution, strictness, holes, full-256 decodes),
// the extract_from_bytes battery, and the three embedded data tables
// (pinned at sha256 level over the generated file bytes).
package webextract

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"os"
	"reflect"
	"sort"
	"strconv"
	"strings"
	"testing"
)

func loadGolden(t *testing.T) map[string]any {
	t.Helper()
	data, err := os.ReadFile("testdata/webextract_pure.golden.json")
	if err != nil {
		t.Fatalf("golden file: %v", err)
	}
	var out struct {
		Corpus map[string]any `json:"corpus"`
	}
	if err := json.Unmarshal(data, &out); err != nil {
		t.Fatalf("golden json: %v", err)
	}
	return out.Corpus
}

func section(t *testing.T, corpus map[string]any, name string) map[string]any {
	t.Helper()
	v, ok := corpus[name].(map[string]any)
	if !ok {
		t.Fatalf("golden section %q missing or wrong shape", name)
	}
	return v
}

func mustHex(t *testing.T, s string) []byte {
	t.Helper()
	b, err := hex.DecodeString(s)
	if err != nil {
		t.Fatalf("bad hex %q: %v", s[:min(40, len(s))], err)
	}
	return b
}

func compareGolden(t *testing.T, path string, got, want any) {
	t.Helper()
	g, w := goldenNormalize(got), goldenNormalize(want)
	if !reflect.DeepEqual(g, w) {
		t.Fatalf("%s mismatch:\n got: %s\nwant: %s", path,
			mustJSON(g), mustJSON(w))
	}
}

func goldenNormalize(v any) any {
	raw, err := json.Marshal(v)
	if err != nil {
		return v
	}
	var out any
	if err := json.Unmarshal(raw, &out); err != nil {
		return v
	}
	return out
}

func mustJSON(v any) string {
	raw, _ := json.Marshal(v)
	return string(raw)
}

func fieldsMap(e Extracted, hasContent bool) map[string]any {
	return map[string]any{
		"title":            e.Title,
		"meta_description": e.MetaDescription,
		"text":             e.Text,
		"is_js_shell":      e.IsJsShell,
		"is_paywall":       e.IsPaywall,
		"charset_used":     e.CharsetUsed,
		"has_content":      hasContent,
	}
}

func fieldsOf(e Extracted) map[string]any {
	return fieldsMap(e, e.HasContent())
}

// stripKeys returns the map without the underscore-prefixed meta keys
// (_body_hex, _header_charset, _input_len).
func stripKeys(m map[string]any) map[string]any {
	out := make(map[string]any, len(m))
	for k, v := range m {
		if strings.HasPrefix(k, "_") {
			continue
		}
		out[k] = v
	}
	return out
}

