func TestGoldenCharsetLadder(t *testing.T) {
	ladder := section(t, loadGolden(t), "charset_ladder")
	bodies := map[string][]byte{
		"hi":           []byte("caf\xe9"),
		"unmapped1252": []byte("x\x81y"),
		"plain":        []byte("plain"),
		"bom16":        []byte("\xff\xfet\x00i\x00t\x00l\x00e\x00"),
		"cjk":          []byte("\xd6\xd0\xce\xc4"),
		"sjis":         []byte("\x93\xfa\x96{"),
		"gb4valid":     []byte("\x81\x30\x81\x30"),
		"gb4gap":       []byte("\x84\x36\xa4\x37"),
	}
	fullRange := make([]byte, 256)
	for i := range fullRange {
		fullRange[i] = byte(i)
	}
	for name, raw := range ladder {
		entry := raw.(map[string]any)
		known := ladderKnown(name)

		// the probes
		probes := entry["probes"].(map[string]any)
		for bname, wantRaw := range probes {
			want := wantRaw.(string)
			var got string
			if !known {
				got = "LookupError"
			} else if res := pyDecode(bodies[bname], name); res == nil {
				got = "UnicodeDecodeError"
			} else {
				got = "ok:" + *res
			}
			if got != want {
				t.Errorf("ladder/%s probe %s = %q, want %q", name, bname, got, want)
			}
		}

		// full256 / holes
		if entry["full256"] == nil {
			// the full byte range must fail to decode
			if known {
				if pyDecode(fullRange, name) != nil {
					t.Errorf("ladder/%s: full256 should fail but decoded", name)
				}
				if entry["hole_count"] == nil {
					t.Errorf("ladder/%s: known name but no hole_count in golden", name)
					continue
				}
				hc := int(entry["hole_count"].(float64))
				holes := 0
				var first16 []int
				for b := 0; b < 256; b++ {
					if pyDecode([]byte{byte(b)}, name) == nil {
						holes++
						if len(first16) < 16 {
							first16 = append(first16, b)
						}
					}
				}
				if holes != hc {
					t.Errorf("ladder/%s: hole count %d, want %d", name, holes, hc)
				}
				var want16 []int
				for _, v := range entry["holes_first16"].([]any) {
					want16 = append(want16, int(v.(float64)))
				}
				if !reflect.DeepEqual(first16, want16) {
					t.Errorf("ladder/%s: holes_first16 %v, want %v", name, first16, want16)
				}
			} else if entry["hole_count"] != nil {
				t.Errorf("ladder/%s: unknown name should have nil holes", name)
			}
		} else {
			full256 := entry["full256"].(string)
			res := pyDecode(fullRange, name)
			if res == nil {
				t.Errorf("ladder/%s: full256 decode failed, want success", name)
				continue
			}
			if *res != full256 {
				t.Errorf("ladder/%s: full256 mismatch (len %d vs %d)",
					name, len(*res), len(full256))
			}
		}
	}
}

func TestGoldenBytesCases(t *testing.T) {
	cases := section(t, loadGolden(t), "bytes_cases")
	for key, raw := range cases {
		want := raw.(map[string]any)
		body := mustHex(t, want["_body_hex"].(string))
		cs := want["_header_charset"].(string)
		got := fieldsOf(ExtractFromBytes(body, cs))
		compareGolden(t, "bytes_cases/"+key, got, stripKeys(want))
	}
}

func TestGoldenEmbeddedTables(t *testing.T) {
	c := section(t, loadGolden(t), "entities_table")
	// sha256 over the generated file bytes — the embedded copy must be
	// the generator's exact output.
	sum := fmt.Sprintf("%x", sha256.Sum256(entitiesJSON))
	if sum != c["sha256"].(string) {
		t.Errorf("entities table sha256 drift: %s", sum)
	}
	if got := len(entities()); got != int(c["count"].(float64)) {
		t.Errorf("entities count = %d, want %d", got, int(c["count"].(float64)))
	}
	spot := c["spot"].(map[string]any)
	for k, raw := range spot {
		if raw == nil {
			if _, ok := entities()[k]; ok {
				t.Errorf("entities spot %q: present, want absent", k)
			}
			continue
		}
		if got := entities()[k]; got != raw.(string) {
			t.Errorf("entities spot %q = %q, want %q", k, got, raw.(string))
		}
	}

	ct := section(t, loadGolden(t), "charsets_table")
	sum = fmt.Sprintf("%x", sha256.Sum256(charsetsJSON))
	if sum != ct["sha256"].(string) {
		t.Errorf("charsets table sha256 drift: %s", sum)
	}
	spotC := ct["spot"].(map[string]any)
	for cs, raw := range spotC {
		e := raw.(map[string]any)
		tables := loadSBTables()
		tt, ok := tables[normalizeCodecName(cs)]
		if !ok {
			t.Fatalf("unexpected charset %q in spot table", cs)
		}
		table := &tt
		for hexKey, wantRaw := range e {
			b := int(mustParseHexByte(t, hexKey))
			if got, want := table[b], int32(wantRaw.(float64)); got != want {
				t.Errorf("charsets %s byte %s = %d, want %d", cs, hexKey, got, want)
			}
		}
	}

	c9 := section(t, loadGolden(t), "cp949_table")
	sum = fmt.Sprintf("%x", sha256.Sum256(cp949JSON))
	if sum != c9["sha256"].(string) {
		t.Errorf("cp949 table sha256 drift: %s", sum)
	}

	rt := section(t, loadGolden(t), "runtime")
	if got := rt["python"].(string); got != "3.12.15" {
		t.Logf("note: golden runtime recorded %q (tables pinned by sha anyway)", got)
	}
}

func TestGoldenDbcsAccept(t *testing.T) {
	c := section(t, loadGolden(t), "dbcs_accept")
	sum := fmt.Sprintf("%x", sha256.Sum256(dbcsAcceptJSON))
	if sum != c["sha256"].(string) {
		t.Errorf("dbcs acceptance table sha256 drift: %s", sum)
	}
	acc := loadDbcsAccept()
	spot := c["spot"].(map[string]any)
	for k, wantRaw := range spot {
		want := wantRaw.(bool)
		var got bool
		parts := strings.Split(k, ".")
		switch {
		case parts[1] == "single":
			b := mustParseHexByte(t, parts[2])
			got = acc[parts[0]].single[b]
		case parts[1] == "pair":
			lead := mustParseHexByte(t, parts[2])
			trail := mustParseHexByte(t, parts[3])
			got = acc[parts[0]].pairAt(lead, trail)
		case parts[1] == "triple":
			b2 := mustParseHexByte(t, parts[2])
			b3 := mustParseHexByte(t, parts[3])
			got = acc[parts[0]].tripleAt(b2, b3)
		default:
			t.Fatalf("bad spot key %q", k)
		}
		if got != want {
			t.Errorf("dbcs spot %q = %v, want %v", k, got, want)
		}
	}
}

func mustParseHexByte(t *testing.T, s string) byte {
	t.Helper()
	v, err := strconv.ParseInt(strings.TrimPrefix(s, "0x"), 16, 32)
	if err != nil || v < 0 || v > 255 {
		t.Fatalf("bad hex byte %q", s)
	}
	return byte(v)
}

// ladderKnown reports whether the ladder resolves the codec name —
// the LookupError fact of the golden.
func ladderKnown(name string) bool {
	ladderOnce.Do(buildLadder)
	_, ok := ladderMap[normalizeCodecName(name)]
	return ok
}
